psis}.number small{display:block;color:<?=$D['gold']?>;font-size:<?=$D['badgeLabel']?>mm;font-weight:900}.valid{position:absolute;left:8mm;bottom:4.8mm;color:<?=$D['gold']?>;font-size:<?=$D['badgeLabel']?>mm}.valid b{display:block;color:#fff;font-size:<?=$D['badgeField']?>mm}.qr{position:absolute;right:7mm;bottom:5.8mm;width:21mm;height:21mm;object-fit:contain;background:#fff;padding:.8mm;border:.48mm solid <?=$D['gold']?>;border-radius:1.6mm}.motto{position:absolute;left:40mm;right:30mm;bottom:2.5mm;text-align:center;color:<?=$D['gold']?>;font-size:1.45mm;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
