@media print{html,body{width:90mm!important;margin:0!important;padding:0!important;background:#fff!important}.sheet{padding:0!important;display:block!important;width:90mm!important}.badge{width:90mm!important;height:120mm!important;box-shadow:none!important;margin:0!important;break-after:page;page-break-after:always}.badge:last-of-type{break-after:auto;page-break-after:auto}.buttons,.note{display:none!important}body.print-front .back-badge{display:none!important}body.print-front .front-badge{break-after:auto!important;page-break-after:auto!important}body.print-back .front-badge{display:none!important}body.print-back .back-badge{break-after:auto!important;page-break-after:auto!important}@page{size:90mm 120mm;margin:0}}
</style></head><body><div class="sheet"><section class="badge front-badge"><div class="slot"></div><div class="title <?=$titleClass?>"><?=e($frontTitle)?></div><img class="crest" src="<?=e($logo)?>" alt="Brasão BAMAB"><img class="photo" src="<?=e($photo)?>" alt="Foto" onerror="this.onerror=null;this.src='<?=e($logo)?>';"><div class="brand"><b>BAMAB</b><small>BANDA AMARAL BRASIL</small></div><div class="name"><small><?=e((string)($x['name_label']??setting('doc_student_name_label','NOME')))?></small><strong class="<?=$nameClass?>"><?=e($name?:'—')?></strong></div><div class="details"><?php if($showPref):?><div class="detail"><small><?=e((string)setting('doc_preferred_name_label','NOME SOCIAL / APELIDO'))?></small><b class="<?=$prefClass?>"><?=e($pref)?></b></div><?php endif;?><div class="detail"><small><?=e((string)($x['role_label']??'FUNÇÃO'))?></small><b class="<?=$roleClass?>"><?=e($role?:'—')?></b></div></div><div class="number"><small><?=e((string)($x['number_label']??'NÚMERO'))?></small><?=e((string)($x['number']??'—'))?></div><div class="valid"><small><?=e((string)setting('doc_validity_label','VALIDADE'))?></small><b><?=e((string)($x['valid']??'—'))?></b></div><?php if($showFrontQr):?><img class="qr" src="<?=e($qr)?>" alt="QR Code"><?php endif;?><?php if($showMotto):?><div class="motto"><?=e((string)setting('doc_motto',''))?></div><?php endif;?></section>
<section class="badge back back-badge"><div class="slot"></div><img class="crest" src="<?=e($logo)?>" alt="Brasão BAMAB"><div class="back-brand"><b>BAMAB</b><small>BANDA AMARAL BRASIL</small></div><div class="back-title <?=$backTitleClass?>"><?=e($backTitle)?></div><div class="back-content"><div class="info"><h3><?=e((string)($x['back_info_title']??'CONTATOS / EMERGÊNCIA'))?></h3><?php foreach($backInfo as $label=>$val):?><div><b><?=e((string)$label)?>:</b> <?=e(trim((string)$val)!==''?(string)$val:'—')?></div><?php endforeach;?></div><div class="rules <?=$rulesClass?>"><h3>REGRAS / INFORMAÇÕES</h3><?=nl2br(e($rules))?></div><div class="verify"><?php if($showBackQr):?><img src="<?=e($qr)?>" alt="QR Code"><?php endif;?><div><b><?=e((string)setting('doc_qr_label','VALIDAÇÃO QR'))?></b><small><?=e((string)($x['number']??'—'))?><br><?=e((string)setting('doc_validity_label','VALIDADE'))?>: <?=e((string)($x['valid']??'—'))?></small></div></div></div><?php if($showMotto):?><div class="back-motto"><?=e((string)setting('doc_motto',''))?></div><?php endif;?></section><div class="buttons"><button type="button" onclick="bamabPrintBadge('both')">IMPRIMIR FRENTE E VERSO</button><button type="button" onclick="bamabPrintBadge('front')">SOMENTE FRENTE</button><button type="button" onclick="bamabPrintBadge('back')">SOMENTE VERSO</button></div><div class="note">Crachá padrão BAMAB: <strong>90 × 120 mm</strong>. Imprima em <strong>100%</strong>, tamanho real, sem ajustar à página e com margens <strong>nenhuma</strong>.</div></div><script>
function bamabAutoFitBadge(el,minPx){if(!el)return;let size=parseFloat(getComputedStyle(el).fontSize)||12;let tries=0;while((el.scrollHeight>el.clientHeight+1||el.scrollWidth>el.clientWidth+1)&&size>minPx&&tries<50){size-=.35;el.style.fontSize=size+'px';tries++;}}
function bamabFitBadge(){document.querySelectorAll('.title,.name strong,.detail b,.number,.valid,.back-title,.info div,.rules,.verify small,.motto,.back-motto').forEach(el=>bamabAutoFitBadge(el,5.2));}
function bamabPrintBadge(mode){document.body.classList.remove('print-front','print-back');if(mode==='front')document.body.classList.add('print-front');if(mode==='back')document.body.classList.add('print-back');bamabFitBadge();setTimeout(()=>window.print(),60);}
window.addEventListener('load',bamabFitBadge);window.addEventListener('afterprint',()=>document.body.classList.remove('print-front','print-back'));
</script></body></html><?php
